import{_ as a,c as n,o as i,ag as t}from"./chunks/framework.ARG558ZT.js";const _=JSON.parse('{"title":"Design decisions, operations and specialist boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"engineering/design.md","filePath":"engineering/design.md"}'),r={name:"engineering/design.md"};function o(s,e,d,l,c,p){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="design-decisions-operations-and-specialist-boundaries" tabindex="-1">Design decisions, operations and specialist boundaries <a class="header-anchor" href="#design-decisions-operations-and-specialist-boundaries" aria-label="Permalink to “Design decisions, operations and specialist boundaries”">​</a></h1><p><strong>Prerequisites:</strong> One working frontend/backend slice and the shared topic foundations. Review baseline: 2026-10-27. All learner practice remains outstanding.</p><h2 id="make-the-decision-reviewable" tabindex="-1">Make the decision reviewable <a class="header-anchor" href="#make-the-decision-reviewable" aria-label="Permalink to “Make the decision reviewable”">​</a></h2><p><a href="./../senior_growth/EngX_Quality/Name_all_steps_that_are_required_to_start_a_new_project%2C_what_kind_of_tools_do_you_suggest_to_use._What_would_you_consider_when_choosing_tech_stack%2C_library%2C_framework.html">Vertical slice/ADR/estimate</a> → <a href="./../senior_growth/EngX_Quality/Could_please_the_differentiate_between_Functional_and_Non-functional_reqs(NFRs)%2C_How_and_when_to_take_them_into_consideration.html">Functional and quality scenarios</a> → <a href="./../senior_growth/EngX_Quality/How_would_you_onboard_new_people_on_a_project%2C_What_kind_of_documentation%2C_style_guide_would_you_use.html">Reproduction and handoff</a>. Separate proposed budgets/owners from observed measurements and real participants; do not invent stakeholder approval.</p><h2 id="map-persistence-explicitly" tabindex="-1">Map persistence explicitly <a class="header-anchor" href="#map-persistence-explicitly" aria-label="Permalink to “Map persistence explicitly”">​</a></h2><p><a href="./../node-js/module-08-postgresql-mikroorm.html">PostgreSQL/SQL/MikroORM</a> and <a href="./../node-js/sql-query-workbench.html">query workbench</a> are the primary intermediate database path, reviewed in round two—not merely the original audit. <a href="./../node-js/module-07-mongodb-mongoose.html">MongoDB</a>, <a href="./../node-js/redis-adapters.html">Redis</a> and <a href="./../node-js/graphql-basics.html">GraphQL</a> are bounded alternatives. <a href="./../senior_growth/EngX_Quality/Do_you_know_some_of_the_differences_of_non_relational_databases_and_relational_databases.html">Data-model comparison</a> must choose actual invariants, topology and isolation, not SQL/NoSQL stereotypes.</p><h2 id="map-distribution-and-operations-explicitly" tabindex="-1">Map distribution and operations explicitly <a class="header-anchor" href="#map-distribution-and-operations-explicitly" aria-label="Permalink to “Map distribution and operations explicitly”">​</a></h2><p><a href="./../node-js/module-12-resilient-distributed-systems.html">Resilient systems</a>, <a href="./../node-js/jobs-and-schedules.html">jobs</a>, <a href="./../node-js/database-recovery.html">database recovery</a>, <a href="./../node-js/module-10-production-ready-applications.html">production lifecycle</a> and <a href="./../node-js/container-deployment-lab.html">containers</a> own retries, idempotency, durable receipts, leases/fencing, recovery and deployment. Their local tests do not prove a production SLO, successful restore in your infrastructure or a multi-region system.</p><h2 id="keep-specialist-depth-bounded" tabindex="-1">Keep specialist depth bounded <a class="header-anchor" href="#keep-specialist-depth-bounded" aria-label="Permalink to “Keep specialist depth bounded”">​</a></h2><p>AWS/IaC, Kubernetes awareness, microfrontends, historical jQuery/Flux/Incremental DOM, advanced RxJS, custom rendering and graph databases are optional introductions/alternatives. Every related local file is still inventoried; optional does not mean unaccounted. Use <a href="./../frontend/">primary browser/workflow patterns</a> before adopting an additional platform.</p><h2 id="python-and-ai-assisted-engineering" tabindex="-1">Python and AI-assisted engineering <a class="header-anchor" href="#python-and-ai-assisted-engineering" aria-label="Permalink to “Python and AI-assisted engineering”">​</a></h2><p><a href="./../python-for-ai/">Python prerequisites</a> and <a href="./../applied-ai/">applied AI</a> retain their completed round-two maps and isolated workbench checks. <a href="./../ai-assisted-engineering/">AI-assisted engineering</a> is a distinct issue→diff→checks→handoff path, now given a standalone retry workbench and separate practice; it is not learner mastery or independent human approval.</p><h2 id="practice-and-verification" tabindex="-1">Practice and verification <a class="header-anchor" href="#practice-and-verification" aria-label="Permalink to “Practice and verification”">​</a></h2><p>Use <a href="./../practice/engineering/">the shared increments</a> and linked focused requirements. <a href="./../workbench/engineering/">Workbench</a> contains canonical references; <a href="./../review/verification.html">verification</a> distinguishes current checks, preserved historical evidence and unperformed integrations.</p>',14)])])}const u=a(r,[["render",o]]);export{_ as __pageData,u as default};
